/* Riders: paginated parcel editing through the hosted POS API. */
class RidersManager {
  constructor(){this.rows=[];this.page=0;this.parcelPage=0;this.busy=false;this.dirty=false;this.view='pickups';}
  e(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  money(n){return (Number(n||0)/100).toFixed(2);}
  can(action){const u=auth.getCurrentUser();let p=[];try{p=JSON.parse(u?.permissions||'[]');}catch{}return u?.role==='admin'||p.includes('riders.'+action);}
  admin(){return auth.getCurrentUser()?.role==='admin';}
  now(){const d=new Date();return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
  id(){return crypto.randomUUID();}
  async api(action,data={}){return API.invoke('riders:'+action,data);}
  async deliver(result){
    if(!result?.success)throw new Error(result?.error||'Unable to prepare the export.');
    if(result.kind==='csv'){
      const url=URL.createObjectURL(new Blob(['\ufeff'+result.content],{type:result.mime||'text/csv;charset=utf-8'}));
      const link=document.createElement('a');link.href=url;link.download=result.filename||'rider-report.csv';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);return;
    }
    if(result.kind==='html'){
      const printWindow=window.open('','_blank','width=980,height=760');
      if(!printWindow)throw new Error('Allow pop-ups to print or save this document as PDF.');
      printWindow.document.open();printWindow.document.write(result.html);printWindow.document.close();return;
    }
    throw new Error('Unsupported export format.');
  }
  button(text,action,permission,extra=''){return !permission||this.can(permission)?`<button type="button" class="btn-secondary" data-action="${action}" ${extra}>${text}</button>`:'';}
  async run(fn){if(this.busy)return;this.busy=true;try{await fn();}catch(e){showToast(e.message,'error');const el=this.host?.querySelector('#rider-message');if(el){el.textContent=e.message;el.hidden=false;}}finally{this.busy=false;}}
  async init(view='pickups'){
    this.view=view;this.host=document.getElementById('tab-riders'+(view==='pickups'?'':view==='payments'?'-payments':'-reports'));
    document.querySelectorAll('.riders-module').forEach(el=>{if(el!==this.host)el.innerHTML='';});
    this.host.classList.add('riders-module');this.host.innerHTML=`<div class="rider-heading"><div><h2>Riders · ${view==='pickups'?'Rider Pickups':view==='payments'?'Payments':'Reports'}</h2><p>Pickup sessions, rider payments and product returns</p></div>${this.button('Refresh','refresh')}${view==='pickups'?this.button('Create New Pickup','new','create'):''}</div><div id="rider-message" role="alert" hidden></div><div id="rider-body"></div><dialog id="rider-dialog"></dialog><dialog id="rider-parcel-dialog"></dialog>`;
    this.host.onclick=e=>{const b=e.target.closest('[data-action]');if(b)this.run(()=>this.action(b.dataset.action,b.dataset));};
    await this.run(()=>this.refresh());
  }
  body(html){this.host.querySelector('#rider-body').innerHTML=html;}
  async refresh(){if(this.view==='reports')return this.reports();if(!this.can('view')){this.body('<p>View pickups permission is required to select and reconcile a pickup.</p>');return;}this.rows=await this.api('list');if(this.view==='payments'){const id=this.pendingPickup;this.pendingPickup=null;await this.paymentPage(id);}else this.pickups();}
  metrics(rows){const keys=[['Active pickups',null],['Parcels handed to riders','parcels'],['Total pickup value','total_cents'],['Amount received','received_cents'],['Outstanding balance','outstanding_cents'],['Expected return pieces','expected'],['Return pieces received','returned'],['Pending return pieces','pending']];const active=rows.filter(x=>x.status!=='Draft');return '<div class="rider-metrics">'+keys.map(([label,key])=>{const value=key?active.reduce((s,p)=>s+p.totals[key],0):rows.filter(p=>p.status==='Active').length;return `<div><span>${label}</span><strong>${key?.endsWith('_cents')?this.money(value):value}</strong></div>`;}).join('')+'</div>';}
  pickups(){this.body(this.metrics(this.rows)+`<section><h3>Pickups</h3><input id="rider-search" type="search" placeholder="Search pickup, rider, parcel or customer" aria-label="Search pickups"><div id="rider-list"></div></section><h3>Recent payments</h3>${this.table(['Pickup','Date','Received by','Method','Amount'],this.rows.flatMap(p=>p.payments.map(x=>({...x,number:p.number}))).sort((a,b)=>b.paid_at.localeCompare(a.paid_at)).slice(0,10).map(x=>[x.number,x.paid_at,x.received_by,x.method,this.money(x.amount_cents)]))}`);this.host.querySelector('#rider-search').oninput=()=>{this.page=0;this.pickupTable();};this.pickupTable();}
  table(headers,rows,raw=false){return `<div class="rider-scroll"><table><thead><tr>${headers.map(h=>'<th>'+this.e(h)+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(v=>'<td>'+(raw?v:this.e(v))+'</td>').join('')+'</tr>').join('')||'<tr><td colspan="99">No records</td></tr>'}</tbody></table></div>`;}
  pickupTable(){const term=this.host.querySelector('#rider-search')?.value.toLowerCase()||'';const rows=this.rows.filter(x=>JSON.stringify([x.number,x.rider_name,x.rider_phone,x.parcels.map(p=>[p.number,p.name])]).toLowerCase().includes(term));this.page=Math.min(this.page,Math.max(0,Math.ceil(rows.length/20)-1));this.host.querySelector('#rider-list').innerHTML=this.table(['Pickup','Date / time','Rider','Parcels','Pieces','Value','Received','Outstanding','Expected / received / pending returns','Payment','Returns','Status','Actions'],rows.slice(this.page*20,this.page*20+20).map(p=>[this.e(p.number||'Draft'),this.e(p.pickup_at.replace('T',' ')),this.e(p.rider_name),p.totals.parcels,p.totals.pieces,this.money(p.totals.total_cents),this.money(p.totals.received_cents),this.money(p.totals.outstanding_cents),`${p.totals.expected} / ${p.totals.returned} / ${p.totals.pending}`,p.totals.payment_status,p.totals.return_status,p.totals.fully_settled&&p.status!=='Draft'?'Fully Settled · '+p.status:p.status,this.button('View','view','view',`data-id="${p.id}"`)+this.button('Edit','edit','edit',`data-id="${p.id}"`)+this.button('Record Payment / Returns','settle','view',`data-id="${p.id}"`)]),true)+`<div class="rider-heading">${this.button('Previous','prev')}<span>Page ${this.page+1} · ${rows.length} pickups</span>${this.button('Next','next')}</div>`;}
  input(label,key,value='',type='text',extra=''){return `<label>${label}<input data-field="${key}" type="${type}" value="${this.e(value)}" ${extra}></label>`;}
  select(label,key,options,value){return `<label>${label}<select data-field="${key}">${options.map(o=>`<option value="${this.e(Array.isArray(o)?o[0]:o)}" ${(Array.isArray(o)?o[0]:o)===value?'selected':''}>${this.e(Array.isArray(o)?o[1]:o)}</option>`).join('')}</select></label>`;}
  readFields(root){return Object.fromEntries([...root.querySelectorAll('[data-field]')].map(x=>[x.dataset.field,x.value]));}
  editable(p){return {...structuredClone(p),parcels:p.parcels.map(x=>({...x,delivery:this.money(x.delivery_cents),products:x.products.map(y=>({...y,price:this.money(y.price_cents)})),returns:x.returns.map(y=>({...y,price:this.money(y.price_cents)}))}))};}
  async editor(p){this.editing=p?this.editable(p):{rider_name:'',rider_phone:'',company:'',pickup_at:this.now(),notes:'',settlement:'informational',parcels:[]};this.parcelPage=0;this.parcelSearch='';this.dirty=false;this.drawEditor();}
  drawEditor(){const p=this.editing,dialog=this.host.querySelector('#rider-dialog');dialog.innerHTML=`<div class="rider-heading"><h2>${this.e(p.number||'New Pickup')}</h2>${this.button('Close','dismiss')}</div><div id="rider-meta" class="rider-fields">${this.input('Rider name *','rider_name',p.rider_name,'text','required')}${this.input('Rider phone *','rider_phone',p.rider_phone,'tel','required')}${this.input('Company','company',p.company)}${this.input('Pickup date / time *','pickup_at',p.pickup_at,'datetime-local','required')}<label>Day<output id="rider-day"></output></label>${this.select('Settlement method','settlement',[['informational','Informational only'],['deduct','Deduct accepted return value']],p.settlement)}${this.input('Notes','notes',p.notes)}</div><p>Save the session, then add parcels. Changes to pickups with payment/return history require Admin access.</p><div class="rider-heading">${this.button(p.id?'Add Parcel':'Save session & Add Parcel','add-parcel')}<input id="rider-parcel-search" type="search" placeholder="Search parcels" aria-label="Search parcels"></div><div id="rider-parcels"></div><div class="rider-sticky"><div id="rider-editor-totals"></div>${this.button(p.status&&p.status!=='Draft'?'Save Changes':'Save Draft','save')}${(!p.status||p.status==='Draft')?this.button('Finish Pickup','finish','finish'):''}</div>`;
    dialog.querySelector('#rider-meta').oninput=()=>{Object.assign(this.editing,this.readFields(dialog.querySelector('#rider-meta')));this.dirty=true;this.day();};dialog.querySelector('[data-field="settlement"]').disabled=!this.admin();dialog.querySelector('#rider-parcel-search').oninput=e=>{this.parcelSearch=e.target.value;this.parcelPage=0;this.drawParcels();};this.day();this.drawParcels();if(!dialog.open)dialog.showModal();dialog.oncancel=e=>{if(this.dirty&&!confirm('Discard unsaved pickup changes?'))e.preventDefault();};}
  day(){const el=this.host.querySelector('#rider-day');if(el)el.textContent=Number.isFinite(Date.parse(this.editing.pickup_at))?new Date(this.editing.pickup_at).toLocaleDateString(undefined,{weekday:'long'}):'';}
  decimal(value){const s=String(value||'0');if(!/^\d+(\.\d{1,2})?$/.test(s))throw new Error('Use at most two decimal places.');const[a,b='']=s.split('.');const n=Number(BigInt(a)*100n+BigInt(b.padEnd(2,'0')));if(!Number.isSafeInteger(n))throw new Error('Amount too large');return n;}
  parcelTotal(p){return p.products.reduce((s,x)=>s+Number(x.quantity)*this.decimal(x.price),this.decimal(p.delivery));}
  drawParcels(){const p=this.editing,rows=p.parcels.map((x,i)=>({x,i})).filter(({x})=>JSON.stringify([x.number,x.name,x.products]).toLowerCase().includes(this.parcelSearch.toLowerCase()));this.parcelPage=Math.min(this.parcelPage,Math.max(0,Math.ceil(rows.length/15)-1));this.host.querySelector('#rider-parcels').innerHTML=this.table(['#','Parcel number','Customer / parcel','Products','Pieces','Total','Expected returns','Actions'],rows.slice(this.parcelPage*15,this.parcelPage*15+15).map(({x,i})=>[i+1,this.e(x.number),this.e(x.name),this.e(x.products.map(y=>y.name).join(', ')),x.products.reduce((s,y)=>s+Number(y.quantity),0),this.money(this.parcelTotal(x)),x.returns.reduce((s,y)=>s+Number(y.quantity),0),this.button('Edit','parcel-edit',null,`data-index="${i}"`)+this.button('Duplicate','parcel-duplicate',null,`data-index="${i}"`)+this.button('Delete','parcel-delete',null,`data-index="${i}"`)]),true)+`<div class="rider-heading">${this.button('Previous','parcel-prev')}<span>Page ${this.parcelPage+1} · ${rows.length} parcels</span>${this.button('Next','parcel-next')}</div>`;this.host.querySelector('#rider-editor-totals').textContent=`${p.parcels.length} parcels · ${p.parcels.reduce((s,x)=>s+x.products.reduce((a,y)=>a+Number(y.quantity),0),0)} pieces · Pickup value ${this.money(p.parcels.reduce((s,x)=>s+this.parcelTotal(x),0))} · Expected returns ${p.parcels.reduce((s,x)=>s+x.returns.reduce((a,y)=>a+Number(y.quantity),0),0)} pieces`;}
  async persist(finish=false,keep=false){const data={...this.editing,finish};const warnings=this.editing.parcels.filter(x=>this.rows.some(p=>p.id!==this.editing.id&&p.status==='Active'&&p.parcels.some(y=>y.number.toLowerCase()===x.number.toLowerCase())));if(warnings.length){if(!confirm('Parcel numbers already exist in other active pickups: '+warnings.map(x=>x.number).join(', ')+'. Continue?'))return false;data.confirm_duplicates=true;}
    if(this.admin()&&this.editing.id&&this.editing.status!=='Draft'){data.confirm_credit=confirm('Save changes to this finished pickup? Any resulting excess payment will remain visible as rider credit.');if(!data.confirm_credit)return false;}
    const saved=await this.api('save',data);this.editing=this.editable(saved);this.dirty=false;showToast('Pickup saved'+(saved.pdf_id?' · PDF saved':'') ,'success');this.rows=await this.api('list');if(keep){this.drawEditor();return true;}this.host.querySelector('#rider-dialog').close();this.pickups();if(finish||saved.status!=='Draft')await this.details(saved.id);return true;}
  blankProduct(){return {name:'',sku:'',quantity:1,price:'0.00',product_id:null};}
  parcelEditor(index,duplicate=false){this.parcelIndex=duplicate?null:index;this.parcel=index==null?{number:'',name:'',phone:'',address:'',delivery:'0.00',notes:'',products:[this.blankProduct()],returns:[]}:structuredClone(this.editing.parcels[index]);if(duplicate){delete this.parcel.id;this.parcel.number='';this.parcel.returns.forEach(x=>delete x.id);}this.drawParcel();}
  drawParcel(){const x=this.parcel,d=this.host.querySelector('#rider-parcel-dialog');d.innerHTML=`<h2>${this.parcelIndex==null?'Add':'Edit'} Parcel</h2><div id="rider-parcel-meta" class="rider-fields">${this.input('Parcel/customer name *','name',x.name,'text','required')}${this.input('Parcel / order / tracking number *','number',x.number,'text','required')}${this.input('Customer phone','phone',x.phone,'tel')}${this.input('Address / city','address',x.address)}${this.input('Delivery charges','delivery',x.delivery,'number','min="0" step="0.01"')}${this.input('Notes','notes',x.notes)}</div><h3>Products</h3><input id="rider-product-search" type="search" aria-label="Search products" placeholder="Search name, SKU, brand or category"><div id="rider-product-results"></div><div id="rider-product-lines"></div>${this.button('Add Product','product-add')}<div class="rider-fields">${this.select('Return Product','return_mode',[['none','No Return Expected'],['expected','Return Product Expected']],x.returns.length?'expected':'none')}</div><div id="rider-return-lines"></div><div id="rider-return-add" ${x.returns.length?'':'hidden'}>${this.button('Add Return Product','return-add')}</div><p id="rider-parcel-total"></p><div class="rider-heading">${this.button('Cancel','parcel-cancel')}${this.button('Save Parcel','parcel-save')}</div>`;
    d.querySelector('#rider-parcel-meta').oninput=()=>{Object.assign(this.parcel,this.readFields(d.querySelector('#rider-parcel-meta')));this.parcelSummary();};d.querySelector('[data-field="return_mode"]').onchange=e=>{if(e.target.value==='none'){if(x.returns.length&&!confirm('Remove expected return products from this parcel?')){e.target.value='expected';return;}x.returns=[];}else if(!x.returns.length)x.returns=[{...this.blankProduct(),reason:'',notes:''}];this.drawLines();};let timer;d.querySelector('#rider-product-search').oninput=e=>{clearTimeout(timer);timer=setTimeout(()=>this.run(async()=>{const results=await this.api('products',{search:e.target.value});this.productResults=results;d.querySelector('#rider-product-results').innerHTML=results.map((p,i)=>this.button(this.e(p.name+' · '+p.code+' · '+p.brand+' · '+p.category),'product-select',null,`data-index="${i}"`)).join('');}),200);};this.drawLines();if(!d.open)d.showModal();}
  drawLines(){const d=this.host.querySelector('#rider-parcel-dialog');for(const [kind,items]of [['product',this.parcel.products],['return',this.parcel.returns]]){d.querySelector('#rider-'+kind+'-lines').innerHTML=items.map((x,i)=>`<fieldset data-kind="${kind}" data-index="${i}"><legend>${kind==='product'?'Product':'Expected return'} ${i+1}</legend><div class="rider-fields">${this.input('Product name *','name',x.name,'text','required')}${this.input('SKU','sku',x.sku)}${this.input('Pieces *','quantity',x.quantity,'number','min="1" step="1" required')}${this.input('Value per piece *','price',x.price,'number','min="0" step="0.01" required')}${kind==='return'?this.input('Return reason','reason',x.reason)+this.input('Notes','notes',x.notes):''}</div>${this.button('Remove '+(kind==='product'?'Product':'Return Product'),kind+'-remove',null,`data-index="${i}"`)}</fieldset>`).join('');d.querySelector('#rider-'+kind+'-lines').oninput=e=>{const set=e.target.closest('fieldset');if(set){Object.assign((kind==='product'?this.parcel.products:this.parcel.returns)[Number(set.dataset.index)],this.readFields(set));this.parcelSummary();}};}d.querySelector('#rider-return-add').hidden=d.querySelector('[data-field="return_mode"]').value==='none';this.parcelSummary();}
  parcelSummary(){try{this.host.querySelector('#rider-parcel-total').textContent='Parcel total: '+this.money(this.parcelTotal(this.parcel))+' · Expected return value: '+this.money(this.parcel.returns.reduce((s,x)=>s+Number(x.quantity)*this.decimal(x.price),0));}catch{this.host.querySelector('#rider-parcel-total').textContent='Enter valid quantities and rates.';}}
  saveParcel(){const d=this.host.querySelector('#rider-parcel-dialog');for(const x of d.querySelectorAll('input'))if(!x.reportValidity())return;if(!this.parcel.name.trim()||!this.parcel.number.trim()||!this.parcel.products.length)throw new Error('Parcel name, number and at least one product are required.');for(const x of [...this.parcel.products,...this.parcel.returns]){if(!x.name.trim()||!Number.isSafeInteger(Number(x.quantity))||Number(x.quantity)<=0)throw new Error('Each product needs a name and positive whole pieces.');this.decimal(x.price);}if(this.editing.parcels.some((x,i)=>i!==this.parcelIndex&&x.number.trim().toLowerCase()===this.parcel.number.trim().toLowerCase()))throw new Error('Duplicate parcel number within this pickup.');if(this.parcelIndex==null)this.editing.parcels.push(this.parcel);else this.editing.parcels[this.parcelIndex]=this.parcel;this.dirty=true;d.close();this.drawParcels();}
  async details(id){const p=await this.api('detail',{id});this.selected=p;const history=await this.api('history',{id});const d=this.host.querySelector('#rider-dialog');d.innerHTML=`<div class="rider-heading"><h2>${this.e(p.number||'Draft')} · ${this.e(p.rider_name)}</h2>${this.button('Close','dismiss')}</div><p>${this.e(p.rider_phone)} · ${this.e(p.company)} · ${this.e(p.pickup_at)} · ${this.e(p.notes)}</p>${this.metrics([p])}<p>Net due: ${this.money(p.totals.net_cents)} · Accepted returns: ${p.totals.accepted} · Credit balance: ${this.money(Math.max(0,-p.totals.outstanding_cents))} · ${p.totals.payment_status} · ${p.totals.return_status} · ${p.totals.fully_settled?'Fully Settled':p.status}</p><div class="rider-heading">${this.button('Edit / Add or Remove Parcels','edit','edit',`data-id="${id}"`)}${p.status!=='Draft'?this.button('Print / Save PDF','pdf','view',`data-id="${id}"`):''}${this.button('Record Payment / Returns','settle','view',`data-id="${id}"`)}${this.button('Complete / Close Pickup','close','finish',`data-id="${id}"`)}${this.button('Delete','delete','delete',`data-id="${id}"`)}</div>${this.table(['#','Parcel','Name','Products / pieces / rates','Total','Expected returns'],p.parcels.map((x,i)=>[i+1,x.number,x.name,x.products.map(y=>y.name+' / '+y.quantity+' × '+this.money(y.price_cents)).join('; '),this.money(x.total_cents),x.returns.map(y=>y.name+' expected '+y.quantity+', accepted '+y.accepted+', pending '+y.pending).join('; ')]))}<h3>Pickup activity</h3>${this.table(['When','Action','User ID'],history.map(x=>[x.created_at,x.action,x.created_by]))}`;this.dirty=false;if(!d.open)d.showModal();}
  paymentPage(id){this.body(`<div class="rider-fields"><label>Rider / Related pickup<select id="rider-payment-pickup"><option value="">Select pickup</option>${this.rows.filter(p=>p.status!=='Draft').map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${this.e(p.rider_name)} · ${this.e(p.number)} · ${this.money(p.totals.outstanding_cents)} outstanding</option>`).join('')}</select></label></div><div id="rider-settlement"></div>`);this.host.querySelector('#rider-payment-pickup').onchange=e=>this.run(()=>this.settlement(e.target.value));if(id)return this.settlement(id);}
  async settlement(id){if(!id){this.host.querySelector('#rider-settlement').innerHTML='';return;}const p=await this.api('detail',{id});this.selected=p;this.paymentRequest=this.id();this.returnRequest=this.id();this.host.querySelector('#rider-settlement').innerHTML=`<h3>${this.e(p.number)} · ${this.e(p.rider_name)}</h3><p>Pickup total ${this.money(p.totals.total_cents)} · Previously received ${this.money(p.totals.received_cents)} · Accepted return value ${this.money(p.totals.return_value_cents)} · Net due ${this.money(p.totals.net_cents)} · Outstanding ${this.money(p.totals.outstanding_cents)}</p><p>${p.totals.payment_status} · ${p.totals.return_status} · ${this.e(p.settlement)} settlement</p>${this.can('payments')?`<section><h3>Record payment</h3><div id="rider-payment-form" class="rider-fields">${this.input('Payment amount *','amount','','number','min="0.01" step="0.01" required')}${this.input('Payment date / time','paid_at',this.now(),'datetime-local','required')}${this.select('Payment method','method',['Cash','Bank Transfer','Easypaisa','JazzCash','Other'],'Cash')}${this.input('Transaction / reference','reference')}${this.input('Notes','notes')}<label>Received by<output>${this.e(auth.getCurrentUser().username)}</output></label></div>${this.button('Save Payment & Receipt','pay','payments')}</section>`:''}<h3>Payments</h3>${this.table(['Date','Amount','Rider credit','Method','Reference','Received by','Receipt'],p.payments.map(x=>[this.e(x.paid_at),this.money(x.amount_cents),this.money(x.credit_cents),this.e(x.method),this.e(x.reference),this.e(x.received_by),this.button('Download','pdf',null,`data-id="${p.id}" data-payment="${x.id}"`)+this.button('Print','print',null,`data-id="${p.id}" data-payment="${x.id}"`)]),true)}<h3>Expected returns</h3>${this.table(['Parcel','Product / SKU','Expected','Previously received','Accepted','Damaged','Missing observations','Pending','Value / piece'],p.parcels.flatMap(x=>x.returns.map(y=>[x.number,y.name+' / '+y.sku,y.quantity,y.received,y.accepted,y.damaged,y.missing,y.pending,this.money(y.price_cents)])))}<p>Damaged and missing pieces remain pending until replacement pieces are accepted. Missing and damaged columns total recorded observations.</p>${this.can('returns')?`<div id="rider-return-form" class="rider-fields">${this.select('Expected return product','expected_id',p.parcels.flatMap(x=>x.returns.filter(y=>y.pending>0).map(y=>[y.id,x.number+' · '+y.name+' · '+y.pending+' pending'])),'')}${this.input('Quantity received now','received','0','number','min="0" step="1"')}${this.input('Accepted quantity','accepted','0','number','min="0" step="1"')}${this.input('Damaged quantity','damaged','0','number','min="0" step="1"')}${this.input('Missing quantity','missing','0','number','min="0" step="1"')}${this.input('Return received date / time','received_at',this.now(),'datetime-local')}${this.input('Notes','notes')}</div>${this.button('Save Return Entry','receive','returns')}`:''}<h3>Return history</h3>${this.table(['Date','Product','Received','Accepted','Damaged','Missing','Value','Notes'],p.returns.map(x=>[x.received_at,p.parcels.flatMap(y=>y.returns).find(y=>y.id===x.expected_id)?.name,x.received,x.accepted,x.damaged,x.missing,this.money(x.accepted*x.price_cents),x.notes]))}${this.button('Complete / Close Pickup','close','finish',`data-id="${p.id}"`)}`;}
  async pay(){const form=this.host.querySelector('#rider-payment-form');for(const x of form.querySelectorAll('input'))if(!x.reportValidity())return;const data={...this.readFields(form),pickup_id:this.selected.id,request_id:this.paymentRequest};if(this.decimal(data.amount)>this.selected.totals.outstanding_cents){if(!this.admin())throw new Error('Payment exceeds outstanding balance.');data.confirm_overpayment=confirm('Confirm intentional overpayment. The excess will be recorded separately as rider credit.');if(!data.confirm_overpayment)return;}await this.api('payment',data);showToast('Payment saved. Use Print / Save PDF for a receipt.','success');await this.settlement(this.selected.id);}
  async receive(){const data={...this.readFields(this.host.querySelector('#rider-return-form')),pickup_id:this.selected.id,request_id:this.returnRequest};const expected=this.selected.parcels.flatMap(p=>p.returns).find(x=>x.id===data.expected_id);if(this.selected.settlement==='deduct'&&expected&&Number(data.accepted)*expected.price_cents>this.selected.totals.outstanding_cents){if(!this.admin())throw new Error('An Admin must confirm returns that create rider credit.');data.confirm_credit=confirm('Accepted returns create rider credit. Confirm this settlement adjustment?');if(!data.confirm_credit)return;}await this.api('returns',data);showToast('Return entry saved','success');await this.settlement(this.selected.id);}
  async reports(){this.body(`<div id="rider-report-filters" class="rider-fields">${this.select('Period','period',['Today','Last 3 days','Last 7 days','This week','This month','Custom period'],'This month')}${this.input('Start date','start',this.now().slice(0,8)+'01','date')}${this.input('End date','end',this.now().slice(0,10),'date')}${this.input('Specific rider','rider','','text','list="rider-report-riders"')}${this.input('Specific pickup','pickup','','text','list="rider-report-pickups"')}<datalist id="rider-report-riders"></datalist><datalist id="rider-report-pickups"></datalist>${this.select('Payment status','payment_status',['','Unpaid','Partially Paid','Paid','Overpaid'],'')}${this.select('Return status','return_status',['','No Return Expected','Return Pending','Partially Returned','Fully Returned','Return Disputed'],'')}${this.select('Pickup status','status',['','Draft','Active','Closed'],'')}${this.select('Payment method','method',['','Cash','Bank Transfer','Easypaisa','JazzCash','Other'],'')}</div><p>Dates select pickups by pickup date. Payment method selects pickups with a matching payment; balances include all their saved payments and returns.</p><div class="rider-heading">${this.button('Apply Filters','report-apply','reports')}${this.button('Print / Save PDF','report-pdf','export')}${this.button('Export CSV / Excel','report-csv','export')}${this.button('Graphical View','report-graph')}${this.button('Text / Table View','report-table')}</div><div id="rider-report-output"></div>`);this.host.querySelector('[data-field="period"]').onchange=e=>{const d=new Date(),end=this.now().slice(0,10);if(e.target.value==='Custom period')return;if(e.target.value==='Last 3 days')d.setDate(d.getDate()-2);if(e.target.value==='Last 7 days')d.setDate(d.getDate()-6);if(e.target.value==='This week')d.setDate(d.getDate()-(d.getDay()+6)%7);if(e.target.value==='This month')d.setDate(1);this.host.querySelector('[data-field="start"]').value=new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,10);this.host.querySelector('[data-field="end"]').value=end;};this.reportCatalog=await this.api('reports',{});const unique=[...new Map(this.reportCatalog.pickups.map(p=>[p.rider_id,p])).values()];this.host.querySelector('#rider-report-riders').innerHTML=unique.map(p=>`<option value="${this.e(p.rider_name+' · '+p.rider_phone)}"></option>`).join('');this.host.querySelector('#rider-report-pickups').innerHTML=this.reportCatalog.pickups.map(p=>`<option value="${this.e(p.number||p.id)}"></option>`).join('');await this.loadReport();}
  filters(){const f=this.readFields(this.host.querySelector('#rider-report-filters'));if(f.start>f.end)throw new Error('Start date must be on or before end date.');if(f.rider){const p=this.reportCatalog.pickups.find(p=>p.rider_name+' · '+p.rider_phone===f.rider);if(!p)throw new Error('Select a rider from the list.');f.rider=p.rider_id;}if(f.pickup){const p=this.reportCatalog.pickups.find(p=>(p.number||p.id)===f.pickup);if(!p)throw new Error('Select a pickup from the list.');f.pickup=p.id;}delete f.period;return f;}
  async loadReport(){this.report=await this.api('reports',this.filters());this.reportPage=0;this.reportView();}
  reportView(graph=false){const r=this.report,out=this.host.querySelector('#rider-report-output');out.innerHTML='<h3>Report totals</h3>'+this.table(['Metric','Value'],Object.entries(r.summary).map(([k,v])=>[k.replace('_cents','').replaceAll('_',' '),k.endsWith('_cents')?this.money(v):v]));if(graph){const max=Math.max(1,...r.daily.map(x=>x.total_cents));out.innerHTML+='<h3>Daily pickup value</h3>'+r.daily.map(x=>`<div class="rider-bar"><span>${this.e(x.label)}</span><meter min="0" max="${max}" value="${x.total_cents}"></meter><strong>${this.money(x.total_cents)}</strong></div>`).join('');return;}
    for(const key of ['riders','daily','weekly'])out.innerHTML+='<h3>'+key+'</h3>'+this.table(['Rider / period','Pickups','Parcels','Value','Net due','Received','Outstanding','Pending returns'],r[key].map(x=>[x.label,x.pickups,x.parcels,this.money(x.total_cents),this.money(x.net_cents),this.money(x.received_cents),this.money(x.outstanding_cents),x.pending]));
    this.reportPage=Math.min(this.reportPage,Math.max(0,Math.ceil(r.pickups.length/10)-1));out.innerHTML+='<h3>Pickup settlement details</h3>'+this.table(['Pickup','Rider','Status','Payment','Returns','Total','Net due','Received','Outstanding'],r.pickups.slice(this.reportPage*10,this.reportPage*10+10).map(p=>[p.number||'Draft',p.rider_name,p.status,p.totals.payment_status,p.totals.return_status,this.money(p.totals.total_cents),this.money(p.totals.net_cents),this.money(p.totals.received_cents),this.money(p.totals.outstanding_cents)]))+`<div class="rider-heading">${this.button('Previous','report-prev')}<span>Page ${this.reportPage+1} · ${r.pickups.length} pickups</span>${this.button('Next','report-next')}</div>`;
    for(const p of r.pickups.slice(this.reportPage*10,this.reportPage*10+10))out.innerHTML+=`<details><summary>${this.e(p.number||'Draft')} · All parcels, products, payments and return entries</summary>`+this.table(['Parcel','Customer','Product','SKU','Pieces','Rate','Line value','Parcel total'],p.parcels.flatMap(x=>x.products.map(y=>[x.number,x.name,y.name,y.sku,y.quantity,this.money(y.price_cents),this.money(y.quantity*y.price_cents),this.money(x.total_cents)])))+this.table(['Parcel','Expected product','Expected','Received','Accepted','Damaged','Missing','Pending','Rate'],p.parcels.flatMap(x=>x.returns.map(y=>[x.number,y.name,y.quantity,y.received,y.accepted,y.damaged,y.missing,y.pending,this.money(y.price_cents)])))+this.table(['Payment date','Amount','Credit','Method','Reference','Received by','Notes'],p.payments.map(x=>[x.paid_at,this.money(x.amount_cents),this.money(x.credit_cents),x.method,x.reference,x.received_by,x.notes]))+this.table(['Return date','Product','Received','Accepted','Damaged','Missing','Value','Notes'],p.returns.map(x=>[x.received_at,p.parcels.flatMap(y=>y.returns).find(y=>y.id===x.expected_id)?.name,x.received,x.accepted,x.damaged,x.missing,this.money(x.accepted*x.price_cents),x.notes]))+'</details>';
  }
  async action(action,d){switch(action){
    case 'refresh':return this.refresh();case 'new':return this.editor();case 'edit':return this.editor(await this.api('detail',{id:d.id}));case 'view':return this.details(d.id);case 'prev':this.page=Math.max(0,this.page-1);return this.pickupTable();case 'next':this.page++;return this.pickupTable();
    case 'dismiss':if(this.dirty&&!confirm('Discard unsaved pickup changes?'))return;this.dirty=false;return this.host.querySelector('#rider-dialog').close();
    case 'add-parcel':if(!this.editing.id&&!(await this.persist(false,true)))return;return this.parcelEditor(null);case 'parcel-edit':return this.parcelEditor(Number(d.index));case 'parcel-duplicate':return this.parcelEditor(Number(d.index),true);case 'parcel-delete':if(confirm('Delete this parcel from the pickup? Save the pickup to apply.')){this.editing.parcels.splice(Number(d.index),1);this.dirty=true;this.drawParcels();}return;
    case 'parcel-prev':this.parcelPage=Math.max(0,this.parcelPage-1);return this.drawParcels();case 'parcel-next':this.parcelPage++;return this.drawParcels();case 'parcel-save':return this.saveParcel();case 'parcel-cancel':return this.host.querySelector('#rider-parcel-dialog').close();case 'save':return this.persist();case 'finish':return this.persist(true);
    case 'product-add':this.parcel.products.push(this.blankProduct());return this.drawLines();case 'product-select':{const p=this.productResults[Number(d.index)];if(this.parcel.products.length===1&&!this.parcel.products[0].name)this.parcel.products=[];this.parcel.products.push({product_id:p.id,name:p.name,sku:p.code,quantity:1,price:Number(p.price).toFixed(2)});return this.drawLines();}case 'product-remove':this.parcel.products.splice(Number(d.index),1);return this.drawLines();case 'return-add':this.parcel.returns.push({...this.blankProduct(),reason:'',notes:''});return this.drawLines();case 'return-remove':this.parcel.returns.splice(Number(d.index),1);return this.drawLines();
    case 'pdf':case 'print':return this.deliver(await this.api('pdf',{pickup_id:d.id,payment_id:d.payment,mode:'print'}));
    case 'settle':{const dialog=this.host.querySelector('#rider-dialog');if(dialog.open)dialog.close();this.pendingPickup=d.id;switchTab('riders-payments');return;}
    case 'pay':return this.pay();case 'receive':return this.receive();case 'close':if(!confirm('Close this pickup? All payment and returns must be settled.'))return;await this.api('close',{id:d.id});showToast('Pickup closed','success');if(this.view==='payments')return this.settlement(d.id);return this.details(d.id);
    case 'delete':{if(!confirm('Delete this pickup? It will be removed from active lists and reports.'))return;const permanent=this.admin()&&confirm('Permanently delete pickup records? Cancel keeps a recoverable database record. Audit history and saved PDFs are retained.');await this.api('delete',{id:d.id,confirm:true,permanent});this.host.querySelector('#rider-dialog').close();return this.refresh();}
    case 'report-apply':return this.loadReport();case 'report-graph':return this.reportView(true);case 'report-table':return this.reportView();case 'report-prev':this.reportPage=Math.max(0,this.reportPage-1);return this.reportView();case 'report-next':this.reportPage++;return this.reportView();case 'report-pdf':case 'report-print':case 'report-csv':return this.deliver(await this.api('export',{filters:this.filters(),format:action==='report-csv'?'csv':'pdf',mode:'print'}));
  }}
}
const ridersManager=new RidersManager();
